# Convert decimal to binary (as string)
def dec_to_bin(n, bits=8):
    return format(n & ((1 << bits) - 1), f'0{bits}b')

# Convert binary string to decimal
def bin_to_dec(b):
    return int(b, 2)

# Convert decimal to hex
def dec_to_hex(n):
    return hex(n)[2:].upper()

# Two's complement negation (8-bit)
def negate_8bit(n):
    return (~n + 1) & 0xFF

# Examples
print(dec_to_bin(45))      # 00101101
print(bin_to_dec('101101')) # 45
print(dec_to_hex(255))      # FF
print(negate_8bit(17))      # 239 (11101111 = -17 in two's complement)
